							print "<tr> <td>8. Адресат</td><td>Полное официальное и сокращенное наименование организации,- получателя документа и почтовый адрес (в соответствии с реквизитом «Адресат»)</td></tr>\n";
							print "<tr> <td>9. Должностное лицо адресат</td><td>Инициалы и фамилия лица</td></tr>\n";
							print "<tr> <td>10. Должность, инициалы и фамилия лица, подписавшего документ</td><td>В соответствии с реквизитом «Подпись»</td></tr>\n";
							print "<tr> <td>11. Должность, инициалы и фамилия исполнителя</td><td>Должность, инициалы и фамилия исполнителя, подготовившего документ</td></tr>\n";
							print "<tr> <td>12. Наименование региона</td><td>В соответствии с данными о местонахождении адресата</td></tr>\n";
							print "<tr> <td>13. Номер бланка</td><td>В соответствии с номером бланка документа</td></tr>\n";
